import{_ as l,o as n,c as s,a6 as e}from"./chunks/framework.BBIckNDn.js";const u=JSON.parse('{"title":"第6章 ポインタとメモリ管理 ── ゲームプログラマの生命線","description":"","frontmatter":{"title":"第6章 ポインタとメモリ管理 ── ゲームプログラマの生命線","study":{"source":"IT教本","kind":"学習ガイド","status":"学習計画・概要","summary":"メモリ関連の不具合には、ダングリングポインタ、二重解放、バッファオーバーラン、 リーク、断片化などがある。用途に応じてカスタムアロケータ(フレーム、 プール、スタックアロケータ)を使うゲームエンジンも多い。"}},"headers":[],"relativePath":"guide/low-level/pointers-and-memory.md","filePath":"guide/low-level/pointers-and-memory.md"}'),i={name:"guide/low-level/pointers-and-memory.md"};function t(o,a,r,c,d,p){return n(),s("div",null,[...a[0]||(a[0]=[e(`<h1 id="第6章-ポインタとメモリ管理-──-ゲームプログラマの生命線" tabindex="-1">第6章 ポインタとメモリ管理 ── ゲームプログラマの生命線 <a class="header-anchor" href="#第6章-ポインタとメモリ管理-──-ゲームプログラマの生命線" aria-label="Permalink to &quot;第6章 ポインタとメモリ管理 ── ゲームプログラマの生命線&quot;">​</a></h1><h2 id="学ぶ理由" tabindex="-1">学ぶ理由 <a class="header-anchor" href="#学ぶ理由" aria-label="Permalink to &quot;学ぶ理由&quot;">​</a></h2><p>メモリ関連の不具合には、ダングリングポインタ、二重解放、バッファオーバーラン、 リーク、断片化などがある。用途に応じて<strong>カスタムアロケータ</strong>(フレーム、 プール、スタックアロケータ)を使うゲームエンジンも多い。 UE5の<code>FMemory</code>/<code>FMallocBinned</code>や UnityのNative Allocatorはその具体例だ。この章は「怖くて触れない領域」を 「設計対象」に変える。</p><h2 id="到達目標" tabindex="-1">到達目標 <a class="header-anchor" href="#到達目標" aria-label="Permalink to &quot;到達目標&quot;">​</a></h2><ul><li>ポインタに関するあらゆる構文(多重・関数・constの位置)を読み書きできる</li><li>プロセスのメモリレイアウト(スタック/ヒープ/静的/コード)を図示できる</li><li>mallocが内部で何をしているか(フリーリスト等)を説明できる</li><li>スタック/プール/フレームアロケータを自力実装できる</li><li>代表的なメモリバグ5種を、症状から原因を推測できる</li></ul><h2 id="前提知識" tabindex="-1">前提知識 <a class="header-anchor" href="#前提知識" aria-label="Permalink to &quot;前提知識&quot;">​</a></h2><p>第3章(メモリ・キャッシュ)、第4章(スタックフレーム)、第5章(C)。</p><h2 id="学ぶ内容" tabindex="-1">学ぶ内容 <a class="header-anchor" href="#学ぶ内容" aria-label="Permalink to &quot;学ぶ内容&quot;">​</a></h2><ol><li><strong>ポインタ完全理解</strong><ul><li>ポインタ型は指す先の型をコンパイラに伝える。値は対象等を指すために使い、 実行時の値に型情報が必ず添付されるわけではない</li><li>ポインタ演算は要素単位。同じ配列の要素と終端の一つ先までという規則を守る (<code>p+1</code>が表す要素間の間隔はsizeof(T)。一つ先のポインタは逆参照しない)</li><li>多重ポインタ(<code>T**</code>は「出力引数」「配列の配列」で頻出)</li><li>constの位置: <code>const T*</code>(このポインタ経由では対象を変更できない)/ <code>T* const</code>(ポインタ自体を変更できない)</li><li>void*(型消去)とキャスト、関数ポインタ(第5章復習)</li><li>宣言の読み方(右左規則): <code>int (*f[4])(char*)</code> を読めるように</li></ul></li><li><strong>プロセスのメモリレイアウト(第8章仮想メモリの予告編)</strong><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>高位 ┌──────────────┐</span></span>
<span class="line"><span>     │ スタック(下に成長)│ ← ローカル変数・戻り番地</span></span>
<span class="line"><span>     │      ↓        │</span></span>
<span class="line"><span>     │   (空き)       │</span></span>
<span class="line"><span>     │      ↑        │</span></span>
<span class="line"><span>     │ ヒープ(上に成長) │ ← malloc/new</span></span>
<span class="line"><span>     ├──────────────┤</span></span>
<span class="line"><span>     │ .bss/.data     │ ← グローバル・static変数</span></span>
<span class="line"><span>     ├──────────────┤</span></span>
<span class="line"><span>     │ .rodata        │ ← 文字列リテラル・定数</span></span>
<span class="line"><span>     ├──────────────┤</span></span>
<span class="line"><span>     │ .text          │ ← 機械語(関数の実体)</span></span>
<span class="line"><span>低位 └──────────────┘</span></span></code></pre></div><ul><li>この図は単純化した配置例。ASLR・複数スレッドのスタック・複数のマッピング等で 実際の配置は異なる。ヒープが必ず一つの連続領域として上へ伸びるわけではない。 自動記憶域の変数も必ずスタックにあるわけではない。実際のアドレスとメモリマップを観察する</li></ul></li><li><strong>ヒープの内部構造</strong><ul><li>典型的なmallocの実装を「OSから大きな領域を確保し、小分けに配る」モデルで学ぶ。 OSへの要求方法(VirtualAlloc/mmap等)や管理方式は、処理系・アロケータで異なる</li><li>フリーリスト、ヘッダ付きチャンク、ビンによるサイズ分類</li><li><strong>断片化</strong>(外部断片化)── 長時間動くゲームの宿敵</li><li>free(p)が領域を識別する管理情報(チャンクのヘッダ等)。配置や検索方法は実装による</li></ul></li><li><strong>カスタムアロケータ(用途に応じた選択)</strong><ul><li><strong>リニア/フレームアロケータ</strong>: ポインタを進めるだけ。フレーム末に一括リセット → 毎フレームの一時データ(描画コマンド、文字列整形)に最適</li><li><strong>スタックアロケータ</strong>: マーカーまで巻き戻せるリニア</li><li><strong>プールアロケータ</strong>: 同一サイズ専用。弾・パーティクルに最適。断片化ゼロ</li><li><strong>アリーナ</strong>: サブシステム毎に領域を分け、丸ごと解放</li><li>実エンジン: UE <code>FMemStack</code>/<code>FMallocBinned2</code>、Unity <code>Allocator.Temp/TempJob/Persistent</code></li></ul></li><li><strong>メモリバグ図鑑(症状→原因の対応表を作る)</strong><ul><li>ダングリングポインタ(解放後使用)/二重解放/リーク/ バッファオーバーラン/未初期化読み/スタック破壊</li><li>それぞれ「どんなクラッシュ・挙動として現れるか」</li><li>検出ツール: ASan(VS/Clangの-fsanitize=address)、VSヒープデバッグ、 Application Verifier、(UEの)Stompマロケータ</li></ul></li><li><strong>所有権という考え方(C++スマートポインタへの橋)</strong><ul><li>「誰がfreeする責任を持つか」を型と規約で表す</li><li>生ポインタ=非所有の参照、という現代の慣習</li></ul></li></ol><h2 id="重要概念" tabindex="-1">重要概念 <a class="header-anchor" href="#重要概念" aria-label="Permalink to &quot;重要概念&quot;">​</a></h2><ul><li><strong>ポインタは「型付きアドレス」</strong>。恐れる対象ではなく計算対象</li><li><strong>確保と解放の対称性・所有権</strong></li><li><strong>汎用アロケータは万能ゆえに遅い</strong> → 用途特化アロケータが速い</li><li><strong>寿命でメモリを設計する</strong>(フレーム寿命/レベル寿命/永続)── エンジン設計の核</li></ul><h2 id="ゲーム開発との関係" tabindex="-1">ゲーム開発との関係 <a class="header-anchor" href="#ゲーム開発との関係" aria-label="Permalink to &quot;ゲーム開発との関係&quot;">​</a></h2><table tabindex="0"><thead><tr><th>現場の事象</th><th>この章の知識</th></tr></thead><tbody><tr><td>ヒットストップ中の不定期スパイク</td><td>mallocのコスト・断片化</td></tr><tr><td>「毎フレームnewするな」ルール</td><td>フレームアロケータの思想</td></tr><tr><td>弾・パーティクルのプール運用</td><td>プールアロケータ</td></tr><tr><td>長時間プレイでのメモリ枯渇</td><td>リーク・断片化</td></tr><tr><td>稀に飛ぶ「Access Violation 0xdddddddd」</td><td>解放後使用(VSのフィルパターン)</td></tr><tr><td>UEのFMemStack/Unity Allocator.Temp</td><td>この章の技術そのもの</td></tr></tbody></table><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><ol><li>スタック・ヒープ・static・コード(関数アドレス)のアドレスを表示し、 自分のプロセスのメモリマップを描け。</li><li><strong>malloc自作</strong>: 固定長バッファ上にヘッダ+フリーリスト方式の my_malloc/my_freeを実装せよ(結合処理は簡易でよい)。</li><li><strong>フレームアロケータ</strong>を実装し、毎フレームreset()する使い方で 1万回のmalloc/freeと速度比較せよ。</li><li><strong>プールアロケータ</strong>を実装し、パーティクル1万個の生成破棄を回せ。</li><li>VSのデバッグヒープで、未初期化(0xCD)・解放済み(0xDD)・ ガード(0xFD)のフィルパターンをメモリウィンドウで確認せよ。</li><li>ASanを有効化し、わざと書いた解放後使用・範囲外書き込みが どう報告されるか確認せよ。</li></ol><h2 id="おすすめ書籍" tabindex="-1">おすすめ書籍 <a class="header-anchor" href="#おすすめ書籍" aria-label="Permalink to &quot;おすすめ書籍&quot;">​</a></h2><ul><li>前橋和弥『C言語 ポインタ完全制覇』── ポインタ和書の定番</li><li>『Game Engine Architecture』メモリ管理の章 ── アロケータ設計の実務</li><li>CS:APP 第9章(動的メモリ割り当て)── mallocの内部の決定版</li><li>glibc malloc / dlmalloc の解説記事(Web)</li></ul><h2 id="おすすめoss" tabindex="-1">おすすめOSS <a class="header-anchor" href="#おすすめoss" aria-label="Permalink to &quot;おすすめOSS&quot;">​</a></h2><ul><li><strong>mimalloc</strong>(microsoft/mimalloc)── 現代的アロケータ。設計docが秀逸</li><li><strong>tlsf</strong>(リアルタイム向けO(1)アロケータ)── ゲーム機で実績。短くて読める</li><li>UE5 <code>FMallocBinned2</code>(第17章で本格読解)</li><li>o1heap ── 小さくて読み切れるアロケータ</li></ul><h2 id="おすすめ動画" tabindex="-1">おすすめ動画 <a class="header-anchor" href="#おすすめ動画" aria-label="Permalink to &quot;おすすめ動画&quot;">​</a></h2><ul><li>CppCon &quot;What Programmers Should Know About Memory Allocation&quot; (Andrei Alexandrescu ほかアロケータ系講演)</li><li>Handmade Hero のメモリアリーナ導入回(Day 34前後)</li><li>GDC &quot;Memory Management in Games&quot; 系講演</li></ul><h2 id="読むべきソースコード" tabindex="-1">読むべきソースコード <a class="header-anchor" href="#読むべきソースコード" aria-label="Permalink to &quot;読むべきソースコード&quot;">​</a></h2><ul><li>tlsf.c(600行程度。フリーリスト+ビンの実物)</li><li>raylib/UE5内の一時バッファ利用箇所(<code>FMemStack</code>検索)</li><li>自作した my_malloc(書いた後にmimalloc docと比較)</li></ul><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><code>const char** argv</code> の型を日本語で正確に述べよ。</li><li>free(p) はなぜ解放サイズを知っているのか?</li><li>ダングリングポインタによるクラッシュが「たまにしか起きない」のはなぜ?</li><li>フレームアロケータはなぜ速いのか。何に使えて何に使えないか。</li><li>断片化とは何か。プールアロケータが断片化しないのはなぜか。</li><li>「所有権」とは何か。生ポインタ・unique_ptr(予告)との関係は?</li><li>0xCDCDCDCD へのアクセス違反を見たら何を疑うか?(VSデバッグヒープ)</li></ol><hr><h2 id="この章がゲームのどこで使われているか" tabindex="-1">この章がゲームのどこで使われているか <a class="header-anchor" href="#この章がゲームのどこで使われているか" aria-label="Permalink to &quot;この章がゲームのどこで使われているか&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1フレームのメモリ活動</span></span>
<span class="line"><span>┌────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 入力処理    : (確保なし ← それが正しい)            │</span></span>
<span class="line"><span>│ ゲーム更新  : 弾生成→プールから取得(mallocしない)  │</span></span>
<span class="line"><span>│              一時計算→フレームアロケータ           │</span></span>
<span class="line"><span>│ 描画       : コマンドバッファ→フレームアロケータ    │</span></span>
<span class="line"><span>│ フレーム末  : フレームアロケータをreset(一括解放)    │</span></span>
<span class="line"><span>├────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ レベルロード時: レベルアリーナに大量確保             │</span></span>
<span class="line"><span>│ レベル終了時 : アリーナ丸ごと解放(リーク原理的にゼロ) │</span></span>
<span class="line"><span>└────────────────────────────────────────────────┘</span></span>
<span class="line"><span>UE: FMemStack/FMallocBinned2  Unity: Allocator.Temp/TempJob/Persistent</span></span>
<span class="line"><span>= この章で作ったものの産業版</span></span></code></pre></div><h2 id="記述の確認資料" tabindex="-1">記述の確認資料 <a class="header-anchor" href="#記述の確認資料" aria-label="Permalink to &quot;記述の確認資料&quot;">​</a></h2><ul><li><a href="https://www.open-std.org/jtc1/sc22/wg14/www/docs/n1570.pdf" target="_blank" rel="noreferrer">WG14 N1570: C11 committee draft (5.1.2.3, 6.2.4, 6.5, 6.7.2.1)</a></li><li><a href="https://eel.is/c++draft/intro.abstract" target="_blank" rel="noreferrer">C++ working draft: Abstract machine</a></li><li><a href="https://learn.microsoft.com/en-us/windows/win32/memory/virtual-address-space" target="_blank" rel="noreferrer">Microsoft: Virtual Address Space</a></li></ul>`,30)])])}const m=l(i,[["render",t]]);export{u as __pageData,m as default};
